const route=useRoute()
type NavItem={label:string;to:string;icon:Component}
const items:NavItem[]=[
 {label:'Vue d’ensemble',to:'/admin',icon:ChartNoAxesCombined},{label:'Rendez-vous',to:'/admin/rendez-vous',icon:CalendarDays},{label:'Calendrier',to:'/admin/calendrier',icon:CalendarRange},{label:'Prestations',to:'/admin/prestations',icon:Paintbrush},{label:'Catégories',to:'/admin/categories',icon:Layers3},{label:'Réalisations',to:'/admin/realisations',icon:Images},{label:'Équipe',to:'/admin/equipe',icon:Users},{label:'Horaires',to:'/admin/horaires',icon:Clock3},{label:'Clientes',to:'/admin/clients',icon:UserRound},{label:'Paiements',to:'/admin/paiements',icon:CreditCard},{label:'Messages',to:'/admin/messages',icon:Mail},{label:'Notifications',to:'/admin/notifications',icon:MessageCircle},{label:'Intégrations',to:'/admin/integrations',icon:KeyRound},{label:'Contenu',to:'/admin/contenu',icon:FileText},{label:'Paramètres',to:'/admin/parametres',icon:Settings2},
]
