const{data:session}=await useFetch<{user:{name:string;email:string};role:string}>('/api/admin/session',{key:'admin-session',default:()=>null as never})
async function logout(){try{await $fetch('/api/auth/sign-out',{method:'POST'})}finally{await navigateTo('/connexion')}}
</script>
